import{_ as e,o as r,c as a,a0 as i}from"./chunks/framework.DJ-9CPBN.js";const p=JSON.parse('{"title":"What is Auditerra?","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),o={name:"overview.md"};function s(n,t,d,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="what-is-auditerra" tabindex="-1">What is Auditerra? <a class="header-anchor" href="#what-is-auditerra" aria-label="Permalink to &quot;What is Auditerra?&quot;">​</a></h1><p>Auditerra is a soil diagnostics and restoration platform that connects smallholder farmers in Kenya with agricultural experts through a low-connectivity digital network. The platform enables farmers to report land degradation issues using basic feature phones, allows experts to collect and verify field data offline, and gives institutional supervisors the tools to monitor restoration progress with verifiable, audit-ready evidence.</p><p>The platform transforms fragmented field observations into actionable restoration plans delivered directly to farmers via SMS, replacing unreliable satellite data with human-verified field measurements.</p><hr><h2 id="the-problem-we-solve" tabindex="-1">The Problem We Solve <a class="header-anchor" href="#the-problem-we-solve" aria-label="Permalink to &quot;The Problem We Solve&quot;">​</a></h2><h3 id="the-ground-truth-gap" tabindex="-1">The Ground-Truth Gap <a class="header-anchor" href="#the-ground-truth-gap" aria-label="Permalink to &quot;The Ground-Truth Gap&quot;">​</a></h3><p>Sub-Saharan Africa faces a severe ecological crisis. Current monitoring relies on satellite data that cannot verify subsurface soil health or localized realities. This creates a ground-truth gap that prevents effective restoration and blocks climate funding.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Scale</th></tr></thead><tbody><tr><td>Arable land actively degraded</td><td>65%</td></tr><tr><td>Productive land lost annually</td><td>12 million hectares</td></tr><tr><td>Fertile soil lost yearly</td><td>75 billion tons</td></tr></tbody></table><p>Satellite data cannot measure:</p><ul><li>Subsurface soil health (pH, nitrogen, phosphorus, potassium)</li><li>Localized socio-economic conditions</li><li>Actual on-the-ground restoration progress</li></ul><hr><h2 id="research-foundation" tabindex="-1">Research Foundation <a class="header-anchor" href="#research-foundation" aria-label="Permalink to &quot;Research Foundation&quot;">​</a></h2><p>Auditerra is built on the Restoration-on-Demand (RoD) case study, a research project examining scalable digital architecture for land restoration in Kenya. The full research report provides the academic foundation and evidence base for the platform design.</p><h3 id="research-structure" tabindex="-1">Research Structure <a class="header-anchor" href="#research-structure" aria-label="Permalink to &quot;Research Structure&quot;">​</a></h3><p><strong>1. Problem Definition</strong> The research identifies that traditional restoration projects fail due to a ground-truth gap where satellite data misreads actual soil health. Smallholder farmers lack agronomic expertise, manual field logs are error-prone, and institutional backers face verification anxieties that freeze funding.</p><p><strong>2. Stakeholder Analysis</strong> The research maps four stakeholder categories that inform the platform&#39;s user design:</p><table tabindex="0"><thead><tr><th>Category</th><th>Stakeholders</th><th>Role</th></tr></thead><tbody><tr><td><strong>Players</strong></td><td>Institutional Supervisors</td><td>Decision-makers who coordinate field efforts and justify resource distribution</td></tr><tr><td><strong>Context Setters</strong></td><td>Agricultural Bodies, National Registries</td><td>Provide verified scientific data and set interoperability standards</td></tr><tr><td><strong>Subjects</strong></td><td>Smallholder Farmers, Field Experts</td><td>Primary users whose livelihoods depend on restoration success</td></tr><tr><td><strong>Crowd</strong></td><td>Commercial Fertilizer Blenders</td><td>Secondary opportunity for monetization through aggregated soil health data</td></tr></tbody></table><p><strong>3. Solution Framework</strong> The research proposes a decentralized digital architecture optimized for low-bandwidth environments that connects smallholders with local experts via USSD and offline-first mobile tools. The framework establishes an immutable audit trail through Three-Tiered Verification: satellite data, physical re-tests, and yield logs.</p><p><strong>4. Verification Methodology</strong></p><ul><li><strong>Security Handshake Protocol</strong>: 4-digit code proves physical expert presence on-site</li><li><strong>60-Day Physical Audit Loop</strong>: Shifts success metrics from planting speed to biological survival and soil recovery</li><li><strong>Geospatial Boundary Mapping</strong>: GPS polygons capture accurate farm perimeters</li></ul><p><strong>5. Technical Architecture</strong></p><ul><li>Offline-first Progressive Web App for field experts</li><li>USSD interface for feature phone farmers</li><li>AI-powered diagnostic engine using Retrieval-Augmented Generation</li><li>PostgreSQL with PostGIS for spatial queries</li><li>IndexedDB for client-side data persistence</li></ul><p><strong>6. Environmental Considerations</strong> The research documents critical hardware limitations in ASAL environments:</p><ul><li>Temperatures exceeding 55°C cause drone batteries to lose 50% of lifespan</li><li>Mineral dust reduces solar panel output by up to 50%</li><li>Fine dust acts as abrasive in motor parts and can cause short circuits</li></ul><p><a href="https://docs.google.com/document/d/18-6IqKA9vsZqwmht3UFp0WH251Kjl0XEdilepeAH_S4/edit?tab=t.0" target="_blank" rel="noreferrer">View the Full Research Report</a></p><hr><h2 id="the-product" tabindex="-1">The Product <a class="header-anchor" href="#the-product" aria-label="Permalink to &quot;The Product&quot;">​</a></h2><p>The Restoration-on-Demand platform translates the research findings into a production-ready system.</p><h3 id="how-it-works-the-four-step-workflow" tabindex="-1">How It Works: The Four-Step Workflow <a class="header-anchor" href="#how-it-works-the-four-step-workflow" aria-label="Permalink to &quot;How It Works: The Four-Step Workflow&quot;">​</a></h3><p><strong>Step 1: Report</strong> The farmer dials the USSD shortcode and reports a soil, crop, or water issue through the menu on their basic feature phone.</p><p><strong>Step 2: Match</strong> The backend engine uses multi-factor scoring to find the nearest qualified expert based on proximity, technical specialization, and language compatibility within a 15km radius.</p><p><strong>Step 3: Verify</strong> The expert travels to the farm, enters the 4-digit Security Handshake code, logs GPS boundaries, and records soil diagnostics offline.</p><p><strong>Step 4: Prescribe</strong> Data syncs to the cloud, the AI generates a prescription, SMS is sent to the farmer, the dashboard is updated, and a 60-day retest is scheduled.</p><h3 id="who-uses-auditerra" tabindex="-1">Who Uses Auditerra? <a class="header-anchor" href="#who-uses-auditerra" aria-label="Permalink to &quot;Who Uses Auditerra?&quot;">​</a></h3><p><strong>1. Farmers (Primary Users)</strong></p><ul><li>Tech comfort: Low (basic feature phone, 2G connectivity)</li><li>Pain points: Only realize trees are dying when it is too late; severe topsoil erosion and nutrient depletion; isolated from centralized agricultural advice</li><li>What they do: Dial USSD shortcode; register with name, phone number, and location; report issues; receive AI-generated prescriptions via SMS; participate in 60-day retest</li></ul><p><strong>2. Field Experts (Secondary Users)</strong></p><ul><li>Tech comfort: High (smartphone user)</li><li>Pain points: Hardware damage from extreme heat; no internet connectivity in remote areas; difficulty tracking large farm perimeters</li><li>What they do: Receive dispatch alerts on PWA; travel to farms and perform Security Handshake; log GPS coordinates and soil diagnostics offline; sync data automatically when signal returns; return for 60-day retest</li></ul><p><strong>3. Institutional Supervisors (Tertiary Users)</strong></p><ul><li>Tech comfort: High</li><li>Pain points: Cannot verify if experts visited farms; no centralized field statistics; difficulty justifying resource allocation to funders</li><li>What they do: Monitor Supervisor Dashboard; track expert deployment densities; audit 60-day retest compliance; export verifiable impact reports</li></ul><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="_1-low-connectivity-first" tabindex="-1">1. Low-Connectivity First <a class="header-anchor" href="#_1-low-connectivity-first" aria-label="Permalink to &quot;1. Low-Connectivity First&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>USSD Interface</strong></td><td>Farmers report issues using basic feature phones. No internet required.</td></tr><tr><td><strong>Offline-First PWA</strong></td><td>Experts work in zero-connectivity zones. Data stores locally in IndexedDB.</td></tr><tr><td><strong>Background Sync</strong></td><td>Automatic data upload when network signal returns.</td></tr></tbody></table><h3 id="_2-verifiable-impact" tabindex="-1">2. Verifiable Impact <a class="header-anchor" href="#_2-verifiable-impact" aria-label="Permalink to &quot;2. Verifiable Impact&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Security Handshake</strong></td><td>4-digit code proves the expert physically visited the farm. Prevents fraud.</td></tr><tr><td><strong>60-Day Audit Loop</strong></td><td>Enforces re-testing. Measures biological survival, not just planting speed.</td></tr><tr><td><strong>Geospatial Boundary Mapping</strong></td><td>GPS polygons capture accurate farm perimeters.</td></tr></tbody></table><h3 id="_3-smart-matching" tabindex="-1">3. Smart Matching <a class="header-anchor" href="#_3-smart-matching" aria-label="Permalink to &quot;3. Smart Matching&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Multi-Factor Scoring</strong></td><td>Matches by proximity (40%), technical specialization (35%), language compatibility (15%).</td></tr><tr><td><strong>Dynamic Radius Expansion</strong></td><td>Searches 15km → 30km → 45km → unlimited until an expert is found.</td></tr><tr><td><strong>Language Compatibility</strong></td><td>Matches farmers with experts who speak their language (English/Kiswahili).</td></tr></tbody></table><h3 id="_4-ai-powered-diagnostics" tabindex="-1">4. AI-Powered Diagnostics <a class="header-anchor" href="#_4-ai-powered-diagnostics" aria-label="Permalink to &quot;4. AI-Powered Diagnostics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>RAG Processing</strong></td><td>Retrieval-Augmented Generation using Gemini Flash</td></tr><tr><td><strong>Three Output Streams</strong></td><td>Farmer SMS (160 chars), Expert Brief, Institutional Dashboard Metrics</td></tr><tr><td><strong>Continuous Learning</strong></td><td>60-day retest cycle validates and improves AI accuracy</td></tr></tbody></table><h3 id="_5-institutional-oversight" tabindex="-1">5. Institutional Oversight <a class="header-anchor" href="#_5-institutional-oversight" aria-label="Permalink to &quot;5. Institutional Oversight&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Supervisor Dashboard</strong></td><td>Interactive national map with verified field data</td></tr><tr><td><strong>Audit-Ready Reports</strong></td><td>Immutable proof-of-impact for global climate funders</td></tr><tr><td><strong>Ticket Tracking</strong></td><td>Real-time status monitoring (PENDING → MATCHED → DISPATCHED → COMPLETED)</td></tr></tbody></table><hr><h2 id="product-requirements" tabindex="-1">Product Requirements <a class="header-anchor" href="#product-requirements" aria-label="Permalink to &quot;Product Requirements&quot;">​</a></h2><p>The platform is designed to meet specific performance targets that align with both the research findings and operational needs. The Product Requirement Document details functional and non-functional requirements, user stories, and acceptance criteria for the implemented system.</p><p><a href="https://docs.google.com/document/d/1LF-cRiHMh0Htt62VxRZfheig9Oym7ZvhVw8IHCi79VI/edit?tab=t.jxeni2ymg3l5#heading=h.u5ellvusl3i2" target="_blank" rel="noreferrer">View the Product Requirement Document</a></p><hr><h2 id="technical-stack" tabindex="-1">Technical Stack <a class="header-anchor" href="#technical-stack" aria-label="Permalink to &quot;Technical Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Backend API</strong></td><td>FastAPI + Python</td><td>REST API, business logic</td></tr><tr><td><strong>Database</strong></td><td>PostgreSQL + PostGIS</td><td>Relational data, spatial queries</td></tr><tr><td><strong>ORM</strong></td><td>SQLAlchemy</td><td>Database abstraction, migrations</td></tr><tr><td><strong>AI</strong></td><td>Google Gemini Flash</td><td>Diagnostic generation</td></tr><tr><td><strong>USSD</strong></td><td>Africa&#39;s Talking</td><td>Feature phone interface</td></tr><tr><td><strong>SMS</strong></td><td>SMS Leopard</td><td>Farmer prescriptions</td></tr><tr><td><strong>Frontend</strong></td><td>React + Next.js</td><td>PWA, Supervisor Dashboard</td></tr><tr><td><strong>Offline</strong></td><td>IndexedDB + Service Workers</td><td>Field data persistence</td></tr><tr><td><strong>Auth</strong></td><td>JWT</td><td>Role-based access control</td></tr><tr><td><strong>Hosting</strong></td><td>Backend: Heroku, Frontend: Vercel</td><td>Production deployment</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/Auditerra-Technical-Documentation-/architecture/overview.html">Architecture</a> : Explore our system architecture</li></ul>',62)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
